### समाधान कोड
```cpp
#include <iostream>
#include <cstring>
#include <string>
using namespace std;

long long count_classy(long long n) {
    if (n == 0) {
        return 0;
    }
    string s = to_string(n);
    int len = s.size();
    long long dp[20][4][2];
    memset(dp, 0, sizeof(dp));
    dp[0][0][1] = 1;

    for (int i = 0; i < len; i++) {
        for (int cnt = 0; cnt <= 3; cnt++) {
            for (int tight = 0; tight < 2; tight++) {
                if (dp[i][cnt][tight] == 0) 
                    continue;
                int lim = tight ? (s[i] - '0') : 9;
                for (int d = 0; d <= lim; d++) {
                    int new_cnt = cnt;
                    if (d != 0) {
                        new_cnt++;
                        if (new_cnt > 3) 
                            continue;
                    }
                    int new_tight = (tight && (d == lim)) ? 1 : 0;
                    dp[i+1][new_cnt][new_tight] += dp[i][cnt][tight];
                }
            }
        }
    }

    long long res = 0;
    for (int cnt = 1; cnt <= 3; cnt++) {
        res += dp[len][cnt][0] + dp[len][cnt][1];
    }
    return res;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int T;
    cin >> T;
    while (T--) {
        long long L, R;
        cin >> L >> R;
        long long ans = count_classy(R) - count_classy(L-1);
        cout << ans << '\n';
    }
    return 0;
}
```

